import { synchronize } from '@nozbe/watermelondb/sync'
import database from './database' // Your initialized DB

async function syncSurveys() {
  await synchronize({
    database,
    pullChanges: async ({ lastPulledAt }) => {
      // 1. Fetch changes from your backend API since lastPulledAt
      const response = await fetch(`https://api.yoursite.com/sync?last_pulled=${lastPulledAt}`)
      const { changes, timestamp } = await response.json()
      return { changes, timestamp }
    },
    pushChanges: async ({ changes, lastPulledAt }) => {
      // 2. Push local changes to your backend
      await fetch(`https://api.yoursite.com/sync`, {
        method: 'POST',
        body: JSON.stringify({ changes, lastPulledAt })
      })
    },
  })
}
