```dart
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:isar/isar.dart';
import 'package:http/http.dart' as http;

class SyncService {
  final Isar isar;

  SyncService(this.isar);

  Future<void> syncPendingData() async {
    // Check connectivity
    final connectivityResult = await Connectivity().checkConnectivity();
    if (connectivityResult == ConnectivityResult.none) return;

    // Fetch unsynced records
    final pendingData = await isar.surveyDatas
        .filter()
        .isSyncedEqualTo(false)
        .findAll();

    for (var data in pendingData) {
      try {
        final response = await http.post(
          Uri.parse('https://your-api.com/survey'),
          body: {'name': data.surveyName, 'notes': data.notes},
        );

        if (response.statusCode == 200) {
          await isar.writeTxn(() async {
            data.isSynced = true;
            await isar.surveyDatas.put(data);
          });
        }
      } catch (e) {
        print("Sync failed: $e");
      }
    }
  }
}
```

