    _initDb();
    // Listen for connection changes to trigger sync
    Connectivity().onConnectivityChanged.listen((result) {
      if (result != ConnectivityResult.none) _syncData();
    });
  }

  Future<void> _initDb() async {
    db = await openDatabase('survey.db', version: 1, onCreate: (db, _) {
      db.execute('CREATE TABLE surveys (id INTEGER PRIMARY KEY, data TEXT, synced INTEGER)');
    });
  }

  // Save to local storage (Offline-First)
  Future<void> _saveSurvey(String surveyData) async {
    await db.insert('surveys', {'data': surveyData, 'synced': 0});
    _syncData(); // Attempt sync immediately
  }

