    final unsynced = await db.query('surveys', where: 'synced = 0');

    for (var row in unsynced) {
      try {
        final response = await http.post(Uri.parse('https://api.example.com/sync'), body: row['data']);
        if (response.statusCode == 200) {
          await db.update('surveys', {'synced': 1}, where: 'id = ?', whereArgs: [row['id']]);
