import 'package:isar/isar.dart';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:http/http.dart' as http;
import 'survey_entry.dart';

class SyncService {
  final Isar isar;
  SyncService(this.isar);

  Future<void> attemptSync() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    if (connectivityResult == ConnectivityResult.none) return;

    // Fetch unsynced records
    final unsynced = await isar.surveyEntrys.filter().isSyncedEqualTo(false).findAll();

    for (var entry in unsynced) {
      try {
        // Mock API Call
        final response = await http.post(Uri.parse('https://api.example.com/sync'), body: entry.data);

        if (response.statusCode == 200) {
          await isar.writeTxn(() async {
            entry.isSynced = true;
            await isar.surveyEntrys.put(entry);
          });
        }
      } catch (e) {
        print("Sync failed: $e");
      }
    }
  }
}
```

