```tsx
import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Send } from 'lucide-react';

// Define the data structure
interface DataPoint {
  time: string;
  value: number;
}

export default function Dashboard() {
  const [data, setData] = useState<DataPoint[]>([]);
  const [inputValue, setInputValue] = useState('');

  // 1. Simulate real-time data incoming from a WebSocket/API
  useEffect(() => {
    const interval = setInterval(() => {
      const newDataPoint = {
        time: new Date().toLocaleTimeString().slice(-8),
        value: Math.floor(Math.random() * 100),
      };
      setData((prev) => [...prev.slice(-19), newDataPoint]); // Keep last 20 points
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  // 2. Handle Form Submission
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue) return;

    const manualPoint = {
      time: new Date().toLocaleTimeString().slice(-8),
      value: parseInt(inputValue),
    };

    setData((prev) => [...prev.slice(-19), manualPoint]);
    setInputValue('');
  };

  return (
    <div className="p-8 max-w-4xl mx-auto space-y-8">
      <h1 className="text-2xl font-bold">Real-Time Dashboard</h1>

      {/* Visualization Section */}
      <div className="h-64 bg-white p-4 rounded-lg shadow border">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={data}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="time" />
            <YAxis />
            <Tooltip />
            <Line type="monotone" dataKey="value" stroke="#2563eb" strokeWidth={2} />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Form Handling Section */}
      <form onSubmit={handleSubmit} className="flex gap-2">
        <input
          type="number"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          placeholder="Inject manual value..."
          className="flex-1 p-2 border rounded"
        />
        <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded flex items-center gap-2">
          <Send size={18} /> Update
        </button>
      </form>
    </div>
  );
}
```

### Why this approach works:

1.  **TypeScript Interfaces:** By defining `interface DataPoint`, we ensure that the chart component never crashes due to malformed data (e.g., missing keys or incorrect types), which is critical for live streaming data.
2.  **State Management:** `useState` is used to maintain the data array. By using `prev.slice(-19)`, we implement a "sliding window" technique, which prevents the browser memory from bloating over time.
3.  **Real-Time Simulation:** The `useEffect` hook acts as a lifecycle manager. It initializes the "connection" (the interval) when the component mounts and cleans it up when it unmounts to prevent memory leaks.
4.  **Responsive Layout:** By using `ResponsiveContainer` from Recharts, the dashboard automatically resizes based on the container width, ensuring it works on both desktop and mobile viewports.
5.  **Form Integration:** The form update function updates the exact same state array as the live feed, demonstrating how to merge user-triggered events with automated real-time data seamlessly.

