### The Code

```tsx
import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface DataPoint { time: string; value: number; }

export default function Dashboard() {
  const [data, setData] = useState<DataPoint[]>([]);
  const [threshold, setThreshold] = useState<number>(50);
  const [inputValue, setInputValue] = useState<string>('');

  // 1. Real-time data simulation (Websocket-like behavior)
  useEffect(() => {
    const interval = setInterval(() => {
      const newDataPoint = {
        time: new Date().toLocaleTimeString().slice(-8),
        value: Math.floor(Math.random() * 100),
      };
      setData((prev) => [...prev.slice(-19), newDataPoint]);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // 2. Form handler
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setThreshold(Number(inputValue));
  };

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">Real-Time Dashboard</h1>

      {/* Form Handling */}
      <form onSubmit={handleSubmit} className="mb-8 p-4 bg-gray-100 rounded">
        <label className="mr-2">Set Alert Threshold:</label>
        <input 
          type="number" 
          className="border p-1"
          onChange={(e) => setInputValue(e.target.value)}
        />
        <button type="submit" className="ml-2 bg-blue-500 text-white px-4 py-1 rounded">Update</button>
      </form>

      {/* Visualisation */}
      <div className="h-64 w-full">
        <ResponsiveContainer>
          <LineChart data={data}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="time" />
            <YAxis domain={[0, 100]} />
            <Tooltip />
            <Line type="monotone" dataKey="value" stroke="#8884d8" isAnimationActive={false} />
            {/* Conditional formatting based on form state */}
            <Line type="monotone" dataKey={() => threshold} stroke="red" strokeDasharray="5 5" />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
```

### Key Components of this Solution:

1.  **State Management (`useState`):** The `data` array maintains the historical state for the chart. React's state management ensures that every time a new data point arrives, the component automatically re-renders the UI.
2.  **`useEffect` (The Real-time Engine):** This hook acts as your "listener." In a production scenario, you would replace the `setInterval` logic with a `webSocket.onmessage` event listener to receive live data from a backend server.
3.  **Visualization (`recharts`):** We use a declarative approach. By passing the data array to the `LineChart`, the library handles the complex math of mapping data points to SVG coordinates automatically.
4.  **Form Handling:** The form captures user input and updates the `threshold` state. The chart reacts instantly because it is data-bound to that state, drawing a red line at the threshold value.
5.  **Performance:** Note the `isAnimationActive={false}` prop in the line chart. For high-frequency real-time dashboards, disabling library animations is a best practice to ensure the UI remains smooth as data updates every few milliseconds.

### How to run this:
1. Initialize a Vite project: `npm create vite@latest my-dashboard -- --template react-ts`
2. Install dependencies: `npm install recharts`
3. Replace the contents of `App.tsx` with the code above.
4. Run `npm run dev`.

