interface Stock {
  symbol: string;
  price: number;
  change: number; // percentage
}

class StockHeatmap {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private stocks: Stock[] = [];
  private transform: d3.ZoomTransform = d3.zoomIdentity;

  constructor(containerId: string) {
    const container = document.getElementById(containerId)!;
    this.canvas = document.createElement('canvas');
    this.ctx = this.canvas.getContext('2d')!;
    container.appendChild(this.canvas);

    this.resize();
    this.setupZoom();
    window.addEventListener('resize', () => this.resize());
  }

  private resize() {
    this.canvas.width = window.innerWidth;
    this.canvas.height = window.innerHeight;
    this.draw();
  }

  private setupZoom() {
    const zoom = d3.zoom<HTMLCanvasElement, any>()
      .scaleExtent([1, 10])
      .on('zoom', (event) => {
        this.transform = event.transform;
        this.draw();
      });

    d3.select(this.canvas).call(zoom);
  }

  public updateData(newData: Stock[]) {
    this.stocks = newData;
    this.draw();
  }

  private draw() {
    const { ctx, canvas, stocks, transform } = this;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    ctx.translate(transform.x, transform.y);
    ctx.scale(transform.k, transform.k);

    const cols = Math.ceil(Math.sqrt(stocks.length));
    const size = 100;

    stocks.forEach((stock, i) => {
      const x = (i % cols) * size;
      const y = Math.floor(i / cols) * size;

      // Dynamic coloring based on performance
      const intensity = Math.min(255, Math.abs(stock.change) * 50);
      ctx.fillStyle = stock.change >= 0 ? `rgb(${100 - intensity}, 200, ${100 - intensity})` : `rgb(200, ${100 - intensity}, ${100 - intensity})`;

      ctx.fillRect(x, y, size - 2, size - 2);
      ctx.fillStyle = 'white';
      ctx.fillText(stock.symbol, x + 5, y + 20);
      ctx.fillText(stock.price.toFixed(2), x + 5, y + 40);
    });

    ctx.restore();
  }
}

