      this.stocks.push({ ticker: `STK${i}`, price: Math.random() * 100, change: (Math.random() - 0.5) * 10 });
    }
  }

  // Simulate WebSocket updates
  public updateStock(ticker: string, newPrice: number) {
    const stock = this.stocks.find(s => s.ticker === ticker);
    if (stock) {
      stock.change = ((newPrice - stock.price) / stock.price) * 100;
      stock.price = newPrice;
      this.render();
    }
  }

  private render() {
    const { width, height } = this.canvas;
    this.ctx.clearRect(0, 0, width, height);

    const size = 50 * this.zoom;
    this.stocks.forEach((stock, i) => {
      const col = i % 10;
      const row = Math.floor(i / 10);

      const x = col * (size + 5) + this.offset.x;
      const y = row * (size + 5) + this.offset.y;

      // Color based on change (Red to Green)
      this.ctx.fillStyle = stock.change >= 0 ? `rgb(0, ${Math.min(255, stock.change * 50)}, 0)` : `rgb(${Math.min(255, Math.abs(stock.change) * 50)}, 0, 0)`;
      this.ctx.fillRect(x, y, size, size);

      this.ctx.fillStyle = 'white';
      this.ctx.font = `${10 * this.zoom}px Arial`;
      this.ctx.fillText(stock.ticker, x + 5, y + 20 * this.zoom);
    });
  }

  private setupInteractions() {
    // Zoom with scroll
    this.canvas.addEventListener('wheel', (e) => {
      this.zoom = Math.max(0.5, this.zoom - e.deltaY * 0.001);
      this.render();
    });

    // Pan with drag
    this.canvas.onmousedown = (e) => {
      const startX = e.clientX - this.offset.x;
      const startY = e.clientY - this.offset.y;

      const onMouseMove = (moveE: MouseEvent) => {
        this.offset.x = moveE.clientX - startX;
        this.offset.y = moveE.clientY - startY;
        this.render();
      };

      window.onmousemove = onMouseMove;
      window.onmouseup = () => window.onmousemove = null;
    };
  }
}

