import * as d3 from 'd3';

interface StockData {
  ticker: string;
  price: number;
  change: number; // percentage
}

const WIDTH = 800;
const HEIGHT = 600;
const COLUMNS = 20;
const ROWS = 20;

// 1. Setup Canvas
const canvas = d3.select('#heatmap-container')
  .append('canvas')
  .attr('width', WIDTH)
  .attr('height', HEIGHT);

const context = canvas.node()?.getContext('2d');

// 2. Generate Mock Data
let stocks: StockData[] = Array.from({ length: COLUMNS * ROWS }, (_, i) => ({
  ticker: `STK${i}`,
  price: Math.random() * 1000,
  change: (Math.random() - 0.5) * 10
}));

// 3. Zoom/Pan Setup
const zoom = d3.zoom<HTMLCanvasElement, any>()
  .scaleExtent([1, 8])
  .on('zoom', (event) => draw(event.transform));

canvas.call(zoom);

// 4. Drawing Logic
function draw(transform: d3.ZoomTransform = d3.zoomIdentity) {
  if (!context) return;

  context.clearRect(0, 0, WIDTH, HEIGHT);
  context.save();
  context.transform(transform.k, 0, 0, transform.k, transform.x, transform.y);

  const tileW = WIDTH / COLUMNS;
  const tileH = HEIGHT / ROWS;

  stocks.forEach((d, i) => {
    const x = (i % COLUMNS) * tileW;
    const y = Math.floor(i / COLUMNS) * tileH;

    // Color based on change (Red to Green)
    context.fillStyle = d.change > 0 ? `rgb(0, ${Math.min(255, 100 + d.change * 20)}, 0)` : `rgb(${Math.min(255, 100 - d.change * 20)}, 0, 0)`;
    context.fillRect(x, y, tileW - 2, tileH - 2);

    context.fillStyle = 'white';
    context.font = '10px Arial';
    context.fillText(d.ticker, x + 2, y + 12);
  });

  context.restore();
}

// 5. Simulate Real-time Updates
setInterval(() => {
  stocks.forEach(d => {
    d.change += (Math.random() - 0.5) * 2;
  });
  draw(d3.zoomTransform(canvas.node()!));
}, 1000);

draw();
```

### Key Technical Notes:
*   **The Zoom/Pan Engine:** `d3.zoom` calculates the transformation matrix (`k`, `x`, `y`). We apply this matrix to the canvas context, which automatically scales and shifts our drawing coordinates without needing to recalculate the underlying data positions.
*   **Performance:** By using `context.fillRect`, we avoid creating thousands of `<div>` or `<rect>` elements, allowing the heatmap to remain responsive even if you expand to 10,000+ stocks.
*   **Real-time Updates:** The `setInterval` acts as a placeholder for a `WebSocket.onmessage` event. In a production environment, you would use a memoized state update to prevent full re-renders if only a subset of stocks change.
*   **Color Mapping:** I used a simple RGB calculation where green intensity correlates to positive change and red to negative. For professional use, replace this with `d3.interpolateRdYlGn`.

