import * as d3 from 'd3';

// 1. Setup Types
interface Stock {
  symbol: string;
  price: number;
  change: number; // percentage
}

class Heatmap {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private stocks: Stock[] = [];
  private transform: d3.ZoomTransform = d3.zoomIdentity;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d')!;
    this.initZoom();
  }

  private initZoom() {
    const zoom = d3.zoom<HTMLCanvasElement, any>()
      .scaleExtent([1, 10])
      .on('zoom', (event) => {
        this.transform = event.transform;
        this.render();
      });

    d3.select(this.canvas).call(zoom);
  }

  // 2. Efficient Rendering Loop
  public render() {
    const { ctx, canvas, transform } = this;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();
    ctx.transform(transform.k, 0, 0, transform.k, transform.x, transform.y);

    const gridSize = 50; // Size per cell
    this.stocks.forEach((stock, i) => {
      const x = (i % 20) * gridSize;
      const y = Math.floor(i / 20) * gridSize;

      // Color mapping: Red (negative) to Green (positive)
      const color = stock.change > 0 
        ? `rgba(0, ${Math.min(255, 100 + stock.change * 50)}, 0, 0.8)` 
        : `rgba(${Math.min(255, 100 + Math.abs(stock.change) * 50)}, 0, 0, 0.8)`;

      ctx.fillStyle = color;
      ctx.fillRect(x, y, gridSize - 2, gridSize - 2);

      // Text labels
      ctx.fillStyle = "white";
      ctx.font = "10px Arial";
      ctx.fillText(stock.symbol, x + 5, y + 20);
    });

    ctx.restore();
  }

  public updateData(newData: Stock[]) {
    this.stocks = newData;
    this.render();
  }
}

// 3. Usage & Real-time Simulation
const canvas = document.getElementById('heatmap') as HTMLCanvasElement;
const heatmap = new Heatmap(canvas);

// Mock real-time feed
setInterval(() => {
  const mockData = Array.from({ length: 100 }, (_, i) => ({
    symbol: `STK${i}`,
    price: Math.random() * 100,
    change: (Math.random() - 0.5) * 10
  }));
  heatmap.updateData(mockData);
}, 2000);
```

