const ctx = canvas.getContext('2d')!;

// Simulation State
let stocks: Stock[] = Array.from({ length: 50 }, (_, i) => ({
    id: `STK${i}`, price: 100 + Math.random() * 50, change: 0, 
    x: (i % 7) * 100, y: Math.floor(i / 7) * 80
}));

