    .scaleExtent([1, 10])
    .on('zoom', (event) => render(event.transform));

d3.select(canvas).call(zoom);

// 3. Render Loop
function render(transform: d3.ZoomTransform = d3.zoomIdentity) {
    context.clearRect(0, 0, width, height);
    const rectSize = 12;

    data.forEach((d, i) => {
        const x = (i % gridSize) * rectSize;
        const y = Math.floor(i / gridSize) * rectSize;

        // Apply Zoom/Pan Transformation
        const zx = transform.applyX(x);
        const zy = transform.applyY(y);

        // Color based on value
        context.fillStyle = d.value > 0 ? `rgb(0, ${Math.min(255, d.value * 5)}, 0)` : `rgb(${Math.min(255, Math.abs(d.value) * 5)}, 0, 0)`;
        context.fillRect(zx, zy, rectSize * transform.k - 1, rectSize * transform.k - 1);
    });
}

// 4. Simulate Real-time WebSocket updates
setInterval(() => {
    const randomIndex = Math.floor(Math.random() * data.length);
    data[randomIndex].value = Math.random() * 100 - 50;
    render(d3.zoomTransform(canvas)); // Re-render with current zoom state
}, 100);

render();
```

