// TaskBoard.tsx
import React, { useState, useEffect } from 'react';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { io } from 'socket.io-client';

const socket = io("http://localhost:3001");

export default function TaskBoard() {
  const [tasks, setTasks] = useState([]);

  useEffect(() => {
    socket.on('init', (data) => setTasks(data.tasks));
    socket.on('task-updated', (newTasks) => setTasks(newTasks));
  }, []);

  const handleDragEnd = (event: any) => {
    const { active, over } = event;
    if (active.id !== over.id) {
      // Reorder logic here
      const newTasks = [...tasks]; // simplified reordering
      setTasks(newTasks);
      socket.emit('update-task', newTasks);
    }
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div className="board">
        {tasks.map(task => (
          <div key={task.id} className="task-card">{task.title}</div>
