### 2. The Drag-and-Drop Board (`app/page.tsx`)
This is the core UI logic.

```tsx
'use client';
import { useState, useEffect } from 'react';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { SortableContext, arrayMove, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import Pusher from 'pusher-js';

const pusher = new Pusher('YOUR_KEY', { cluster: 'YOUR_CLUSTER' });

export default function Board() {
  const [tasks, setTasks] = useState([{ id: '1', title: 'Task 1' }, { id: '2', title: 'Task 2' }]);

  useEffect(() => {
    const channel = pusher.subscribe('board-channel');
    channel.bind('task-moved', (data: any) => {
      // Sync state when another user moves a card
      setTasks(data.tasks); 
    });
  }, []);

  const onDragEnd = async (event: any) => {
    const { active, over } = event;
    if (active.id !== over.id) {
      const oldIndex = tasks.findIndex((t) => t.id === active.id);
      const newIndex = tasks.findIndex((t) => t.id === over.id);
      const newTasks = arrayMove(tasks, oldIndex, newIndex);

      setTasks(newTasks);
      await fetch('/api/pusher', { method: 'POST', body: JSON.stringify({ tasks: newTasks }) });
    }
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={onDragEnd}>
      <div className="p-10">
        {tasks.map(task => <TaskItem key={task.id} id={task.id} title={task.title} />)}
      </div>
    </DndContext>
  );
}

function TaskItem({ id, title }: { id: string, title: string }) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({ id });
  const style = { transform: CSS.Transform.toString(transform), transition };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners} className="p-4 bg-white border mb-2 cursor-grab shadow">
      {title}
    </div>
  );
}
```

### Why this approach works:
1.  **Declarative UI:** By using `dnd-kit`, the drag-and-drop handles complex input events (mouse, touch, keyboard) without forcing you to manually manipulate the DOM.
2.  **State Sync:** The `useEffect` hook ensures your application acts as a "subscriber." Whenever a `task-moved` event arrives from the WebSocket, the local state updates instantly, causing React to re-render the board for the second user.
3.  **Minimalist:** This avoids a heavy backend database for this prototype; the "source of truth" for the real-time movement is the state broadcast over Pusher, which is the standard pattern for high-speed collaboration tools.

**Note:** To make this production-ready, you would replace the state update with a database mutation (e.g., PostgreSQL via Prisma) inside the `api/pusher` route so the order persists after a page refresh.

