```cpp
#include <iostream>
#include <atomic>
#include <vector>
#include <thread>

// A simple fixed-size ring buffer for lock-free communication
// In production, you would use a header-only library like 'Disruptor-cpp'
template<typename T, size_t Size>
class LockFreeQueue {
public:
    bool try_push(const T& item) {
        size_t head = head_.load(std::memory_order_relaxed);
        size_t next_head = (head + 1) % Size;
        if (next_head == tail_.load(std::memory_order_acquire)) return false;
        buffer_[head] = item;
        head_.store(next_head, std::memory_order_release);
        return true;
    }

    bool try_pop(T& item) {
        size_t tail = tail_.load(std::memory_order_relaxed);
        if (tail == head_.load(std::memory_order_acquire)) return false;
        item = buffer_[tail];
        tail_.store((tail + 1) % Size, std::memory_order_release);
        return true;
    }

private:
    T buffer_[Size];
    std::atomic<size_t> head_{0};
    std::atomic<size_t> tail_{0};
};

struct Order {
    int id;
    double price;
    int quantity;
};

// --- Execution Loop ---
void matching_engine(LockFreeQueue<Order, 1024>& input_queue) {
    Order order;
    while (true) {
        if (input_queue.try_pop(order)) {
            // Hot Path: Minimal logic, no allocations, no locks
            // Matching logic goes here
            std::cout << "Matching Order: " << order.id << std::endl;
        }
        // CPU hint: prevent tight loop burning 100% core if empty
        _mm_pause(); 
    }
}

int main() {
    LockFreeQueue<Order, 1024> order_queue;

    // Start matching engine on a dedicated core
    std::thread engine(matching_engine, std::ref(order_queue));

    // Simulate Gateway receiving an order
    order_queue.try_push({1, 150.25, 100});

    engine.join();
    return 0;
}
```

### Why this scales and stays fast:

1.  **Memory Locality:** The use of a fixed-size `buffer_` ensures that the data stays in CPU L1/L2 cache, preventing expensive main-memory fetches.
2.  **Lock-Free Concurrency:** We use `std::atomic` with explicit memory orderings (`acquire`/`release`). This avoids the kernel-level context switching associated with `std::mutex` or `std::lock_guard`.
3.  **`_mm_pause()`:** This is a CPU intrinsic that signals to the processor that the thread is in a spin-wait loop, saving power and allowing the hyper-thread on the same physical core to run faster.
4.  **Zero Allocation:** There are no `new` or `malloc` calls in the critical path. All structures are stack-allocated or pre-allocated. In a production system, you would use a custom **Memory Pool** to manage order objects.
