```go
package main

import (
	"fmt"
	"sync"
	"time"
)

// Trade represents incoming market data
type Trade struct {
	Symbol string
	Price  float64
}

// MarketProcessor manages state and subscribers
type MarketProcessor struct {
	mu           sync.RWMutex
	ewma         float64
	subscribers  map[chan float64]struct{}
	alpha        float64 // Smoothing factor
}

func NewMarketProcessor(alpha float64) *MarketProcessor {
	return &MarketProcessor{
		subscribers: make(map[chan float64]struct{}),
		alpha:       alpha,
	}
}

// Process handles incoming trades and updates the EWMA
func (p *MarketProcessor) Process(t Trade) {
	p.mu.Lock()
	// EWMA calculation: S_t = α * P_t + (1 - α) * S_{t-1}
	if p.ewma == 0 {
		p.ewma = t.Price
	} else {
		p.ewma = (p.alpha * t.Price) + ((1 - p.alpha) * p.ewma)
	}
	currentEWMA := p.ewma

	// Stream to all subscribers
	for sub := range p.subscribers {
		select {
		case sub <- currentEWMA:
		default: // Skip if subscriber is slow to prevent blocking the pipeline
		}
	}
	p.mu.Unlock()
}

// Subscribe returns a channel that will receive price updates
func (p *MarketProcessor) Subscribe() chan float64 {
	p.mu.Lock()
	defer p.mu.Unlock()
	ch := make(chan float64, 10)
	p.subscribers[ch] = struct{}{}
	return ch
}

func main() {
	processor := NewMarketProcessor(0.3)

	// Create a subscriber
	sub := processor.Subscribe()
	go func() {
		for val := range sub {
			fmt.Printf("Subscriber received aggregate: %.2f\n", val)
		}
	}()

	// Simulate incoming market data
	prices := []float64{100.0, 101.5, 102.0, 101.8, 103.2}
	for _, p := range prices {
		processor.Process(Trade{Symbol: "BTC", Price: p})
		time.Sleep(100 * time.Millisecond)
	}
}
```

