use std::sync::{Arc, atomic::{AtomicU64, Ordering}};
use tokio::sync::broadcast;
use std::time::Duration;

// Represents the aggregated state of a specific asset
struct PriceAggregator {
    total_price: AtomicU64, // Stored as scaled integer to avoid floating point overhead
    count: AtomicU64,
}

impl PriceAggregator {
    fn new() -> Self {
        Self { total_price: AtomicU64::new(0), count: AtomicU64::new(0) }
    }

    // Update the aggregate (Lock-free)
    fn add_price(&self, price: u64) {
        self.total_price.fetch_add(price, Ordering::Relaxed);
        self.count.fetch_add(1, Ordering::Relaxed);
    }

    fn get_average(&self) -> f64 {
        let t = self.total_price.load(Ordering::Relaxed);
        let c = self.count.load(Ordering::Relaxed);
        if c == 0 { 0.0 } else { t as f64 / c as f64 }
    }
}

#[tokio::main]
async fn main() {
    let aggregator = Arc::new(PriceAggregator::new());
    // Create a broadcast channel for subscribers
    let (tx, _) = broadcast::channel::<f64>(16);

