```rust
use std::sync::{Arc, RwLock};
use tokio::sync::broadcast;
use tokio::time::{self, Duration};

// The structure of our incoming market data
#[derive(Debug, Clone)]
struct Tick {
    symbol: String,
    price: f64,
}

// The structure of our computed aggregate
#[derive(Debug, Clone)]
struct Aggregate {
    symbol: String,
    avg_price: f64,
}

struct PriceProcessor {
    // Shared state to store running totals
    state: Arc<RwLock<std::collections::HashMap<String, (f64, u32)>>>,
    // Channel to broadcast results to subscribers
    tx: broadcast::Sender<Aggregate>,
}

impl PriceProcessor {
    fn new() -> Self {
        let (tx, _) = broadcast::channel(1024);
        Self {
            state: Arc::new(RwLock::new(std::collections::HashMap::new())),
            tx,
        }
    }

    // Process an incoming tick
    fn process_tick(&self, tick: Tick) {
        let mut map = self.state.write().unwrap();
        let entry = map.entry(tick.symbol.clone()).or_insert((0.0, 0));
        entry.0 += tick.price;
        entry.1 += 1;
    }

    // Background task to push aggregates to subscribers
    async fn start_broadcaster(&self) {
        let mut interval = time::interval(Duration::from_secs(1));
        loop {
            interval.tick().await;
            let map = self.state.read().unwrap();
            for (symbol, (sum, count)) in map.iter() {
                let agg = Aggregate {
                    symbol: symbol.clone(),
                    avg_price: sum / (*count as f64),
                };
                let _ = self.tx.send(agg);
            }
        }
    }
}

#[tokio::main]
async fn main() {
    let processor = Arc::new(PriceProcessor::new());

    // Spawn the broadcaster
    let proc_clone = processor.clone();
    tokio::spawn(async move {
        proc_clone.start_broadcaster().await;
    });

    // Simulate incoming feed
    let p = processor.clone();
    tokio::spawn(async move {
        p.process_tick(Tick { symbol: "BTC".to_string(), price: 50000.0 });
