```rust
use tokio::sync::broadcast;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Duration;

// A simple structure to hold aggregated price data
#[derive(Clone, Debug)]
struct PriceAggregate {
    symbol: String,
    avg_price: f64,
    tick_count: u64,
}

struct Aggregator {
    total_price: AtomicU64, // Using bits to store f64 for atomic updates
    count: AtomicU64,
}

impl Aggregator {
    fn new() -> Self {
        Self {
            total_price: AtomicU64::new(0.0f64.to_bits()),
            count: AtomicU64::new(0),
        }
    }

    fn update(&self, price: f64) -> PriceAggregate {
        let new_count = self.count.fetch_add(1, Ordering::Relaxed) + 1;

        // Simple atomic update loop for the total price
        loop {
            let current_bits = self.total_price.load(Ordering::Relaxed);
            let current_price = f64::from_bits(current_bits);
            let new_price = current_price + price;
            if self.total_price.compare_exchange_weak(
                current_bits, new_price.to_bits(), Ordering::Relaxed, Ordering::Relaxed
            ).is_ok() {
                return PriceAggregate {
                    symbol: "BTC-USD".to_string(),
                    avg_price: new_price / new_count as f64,
                    tick_count: new_count,
                };
            }
        }
    }
}

#[tokio::main]
async fn main() {
    let (tx, _) = broadcast::channel(16);
    let aggregator = Aggregator::new();

    // Subscriber Task: Simulates a connected client
    for i in 0..3 {
        let mut rx = tx.subscribe();
        tokio::spawn(async move {
            while let Ok(msg) = rx.recv().await {
                println!("Subscriber {} received: {:?}", i, msg);
            }
        });
    }

    // Processor Task: Consumes "raw" ticks and broadcasts aggregates
    loop {
        let simulated_tick = 50000.0 + (rand::random::<f64>() * 100.0);
        let aggregate = aggregator.update(simulated_tick);

        let _ = tx.send(aggregate);

        tokio::time::sleep(Duration::from_millis(500)).await;
    }
}
```

### Key Architectural Features:

1.  **Wait-Free/Lock-Free Aggregation:** Instead of using a `Mutex` (which would cause thread contention and latency spikes), we use `AtomicU64` with `compare_exchange` to update the price aggregates. This ensures that the ingest thread is never blocked by a slow subscriber.
2.  **Broadcast Fan-out:** We utilize `tokio::sync::broadcast`. This is highly optimized for "one-to-many" messaging. If a subscriber is too slow, the broadcast channel will return an error, allowing the processor to drop messages for that specific client rather than backing up the entire system.
3.  **Memory Efficiency:** The `PriceAggregate` struct is `Copy` and very small, ensuring that we aren't creating heavy objects on the heap for every tick calculation, reducing pressure on the system.
4.  **Async/Await:** By using `tokio`, the system can handle thousands of concurrent TCP connections (subscribers) with minimal memory overhead, as each connection is managed as a lightweight task rather than an OS thread.

