#include <iostream>
#include <vector>
#include <functional>
#include <mutex>
#include <thread>
#include <atomic>

struct Trade {
    double price;
    double size;
};

// Simple aggregate structure
struct Aggregate {
    double vwap;
    double total_volume;
};

class MarketDataProcessor {
private:
    double running_sum = 0.0;
    double total_volume = 0.0;
    std::mutex mtx;
    std::vector<std::function<void(Aggregate)>> subscribers;

public:
    // Process incoming tick and update state
    void process_tick(const Trade& trade) {
        std::lock_guard<std::mutex> lock(mtx);

        running_sum += (trade.price * trade.size);
        total_volume += trade.size;

        Aggregate agg = { running_sum / total_volume, total_volume };

        // Notify all subscribers
        for (const auto& callback : subscribers) {
            callback(agg);
        }
    }

    void subscribe(std::function<void(Aggregate)> callback) {
        std::lock_guard<std::mutex> lock(mtx);
        subscribers.push_back(callback);
    }
};

int main() {
    MarketDataProcessor processor;

    // Subscriber 1: Logging to console
    processor.subscribe([](Aggregate agg) {
        std::cout << "[Sub 1] New VWAP: " << agg.vwap 
                  << " | Vol: " << agg.total_volume << std::endl;
