        std::vector<Trade> mock_ticks = {{100.5, 10}, {100.7, 5}, {100.6, 20}};
        for (const auto& tick : mock_ticks) {
            processor.process_tick(tick);
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        }
    });

    feed.join();
    return 0;
}
```

