### High-Frequency Messaging Router (C++)

This example uses a lock-free approach to route messages. For brevity, it demonstrates a single-producer-single-consumer circular buffer.

```cpp
#include <iostream>
#include <vector>
#include <atomic>
#include <chrono>
#include <thread>

// Simple message structure
struct Message {
    uint64_t id;
    uint64_t timestamp;
    char payload[64];
};

// A simple Lock-Free Circular Buffer (Ring Buffer)
template<size_t Size>
class RingBuffer {
    Message buffer[Size];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Size;
        if (next_t == head.load(std::memory_order_acquire)) return false; // Buffer full
        buffer[t] = msg;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false; // Buffer empty
        msg = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};

// Routing Engine
void router_worker(RingBuffer<65536>& queue) {
    Message msg;
    uint64_t total_latency = 0;
    uint64_t count = 0;

    while (true) {
        if (queue.pop(msg)) {
            // Monitor Latency
            auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            total_latency += (now - msg.timestamp);
            count++;

            if (count % 1000000 == 0) {
                std::cout << "Avg Latency: " << (total_latency / count) << " ns" << std::endl;
            }
        }
    }
}

int main() {
    RingBuffer<65536> queue;
    std::thread worker(router_worker, std::ref(queue));

    // Simulation of Producer
    for (uint64_t i = 0; i < 10000000; ++i) {
        Message m{i, (uint64_t)std::chrono::high_resolution_clock::now().time_since_epoch().count(), "data"};
        while (!queue.push(m)) { /* Busy spin */ }
    }

