template<size_t Capacity>
class SPSCQueue {
    Message buffer[Capacity];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Capacity;
        if (next_t == head.load(std::memory_order_acquire)) return false;
        buffer[t] = msg;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h];
        head.store((h + 1) % Capacity, std::memory_order_release);
        return true;
    }
};

// Global Queue for demonstration
SPSCQueue<65536> message_queue;

// Producer Thread
void producer() {
    for (uint64_t i = 0; i < 10'000'000; ++i) {
        Message m{i, (uint64_t)std::chrono::high_resolution_clock::now().time_since_epoch().count(), 1.0};
        while (!message_queue.push(m)); // Spin-wait (Busy-loop for lowest latency)
    }
}

// Consumer Thread (Latency Monitor)
void consumer() {
    Message m;
    uint64_t total_latency = 0;
    size_t count = 0;

