template<typename T, size_t Size>
class RingBuffer {
    std::array<T, Size> buffer;
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool push(const T& item) {
        size_t h = head.load(std::memory_order_relaxed);
        size_t next_h = (h + 1) % Size;
        if (next_h == tail.load(std::memory_order_acquire)) return false;
        buffer[h] = item;
        head.store(next_h, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        size_t t = tail.load(std::memory_order_relaxed);
        if (t == head.load(std::memory_order_acquire)) return false;
        item = buffer[t];
        tail.store((t + 1) % Size, std::memory_order_release);
        return true;
    }
};

struct Message {
    uint64_t id;
    uint64_t timestamp_ns;
};

// The Router Logic
void router_worker(RingBuffer<Message, 1024 * 64>& queue) {
    Message msg;
    uint64_t total_latency = 0;
    uint64_t count = 0;

