            uint64_t now = std::chrono::steady_clock::now().time_since_epoch().count();
            total_latency += (now - msg.timestamp_ns);
            count++;

            // Periodically report latency
            if (count % 1000000 == 0) {
                std::cout << "Avg Latency: " << (total_latency / count) << "ns" << std::endl;
            }
        }
    }
}

