#include <iostream>
#include <atomic>
#include <vector>
#include <chrono>
#include <thread>

// A simple lock-free circular buffer for high-speed message passing
template<typename T, size_t Capacity>
class RingBuffer {
    std::vector<T> buffer{Capacity};
    std::atomic<size_t> head{0}, tail{0};
public:
    bool try_push(const T& val) {
        size_t t = tail.load(std::memory_order_relaxed);
        if (t - head.load(std::memory_order_acquire) >= Capacity) return false;
        buffer[t % Capacity] = val;
        tail.store(t + 1, std::memory_order_release);
        return true;
    }

    bool try_pop(T& val) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        val = buffer[h % Capacity];
        head.store(h + 1, std::memory_order_release);
        return true;
    }
};

struct Message {
    uint64_t id;
    std::chrono::steady_clock::time_point timestamp;
};

void consumer(RingBuffer<Message, 65536>& q, std::atomic<bool>& running) {
    Message msg;
    uint64_t count = 0;
    while (running) {
        if (q.try_pop(msg)) {
            auto latency = std::chrono::steady_clock::now() - msg.timestamp;
            count++;
            if (count % 1000000 == 0) { // Report every million
                std::cout << "Latency: " << std::chrono::duration_cast<std::chrono::microseconds>(latency).count() << "us\n";
            }
        }
    }
}

int main() {
    RingBuffer<Message, 65536> queue;
    std::atomic<bool> running{true};

    std::thread worker(consumer, std::ref(queue), std::ref(running));

    // Producer Loop
    for (uint64_t i = 0; i < 10000000; ++i) {
        while (!queue.try_push({i, std::chrono::steady_clock::now()})) {
            // Spin-wait (Busy-wait) to keep latency low
        }
    }

    std::this_thread::sleep_for(std::chrono::seconds(1));
    running = false;
    worker.join();
    return 0;
}
```

