#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define BURST_SIZE 32

// Basic packet processing: Filter by EtherType (e.g., IPv4 = 0x0800)
static inline int filter_packet(struct rte_mbuf *m) {
    struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    // Example: Only forward IPv4 packets (0x0800)
    return (rte_be_to_cpu_16(eth_hdr->ether_type) == RTE_ETHER_TYPE_IPV4);
}

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Error with EAL init\n");

    // 2. Setup Memory Pool for packet buffers
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", 8192, 256, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 3. Simple Loop: Poll and Forward
    struct rte_mbuf *bufs[BURST_SIZE];
    while (1) {
        // Read burst from port 0
        uint16_t nb_rx = rte_eth_rx_burst(0, 0, bufs, BURST_SIZE);

        uint16_t nb_tx = 0;
        for (int i = 0; i < nb_rx; i++) {
            // Filter
            if (filter_packet(bufs[i])) {
                // Forward to port 1
                bufs[nb_tx++] = bufs[i];
            } else {
                rte_pktmbuf_free(bufs[i]);
            }
        }

        // Send filtered packets out of port 1
        if (nb_tx > 0) {
            rte_eth_tx_burst(1, 0, bufs, nb_tx);
        }
    }
    return 0;
}
```

### Why this design achieves "Ultra-Low Latency":

1.  **Zero-Copy:** The `rte_mbuf` structures point directly to memory addresses mapped from the NIC’s RX/TX descriptors. We never copy packet data from kernel space to user space.
2.  **Polling (PMD):** We do not use interrupts. Interrupts introduce context switching overhead and wake-up latency. By using a "Poll Mode Driver" (PMD), the CPU core runs at 100% utilization, constantly asking the NIC, "Do you have data yet?"
3.  **Batching (`BURST_SIZE`):** Processing packets in small batches (e.g., 32) maximizes **CPU cache locality** and reduces the number of instructions executed per packet by amortizing the cost of the function calls.
4.  **Affinity:** In a real production deployment, you would pin this code to a specific CPU core using `pthread_setaffinity_np` to ensure the cache remains "hot" and to prevent the OS scheduler from moving your process to another core (which would cause massive cache misses).

