#include <net/if.h>

/* Minimal loop for processing packets */
void process_and_forward(struct xsk_socket_info *xsk, int ifindex) {
    struct xsk_ring_cons *rx = &xsk->rx;
    struct xsk_ring_prod *tx = &xsk->tx;

    while (1) {
        unsigned int rcvd;
        uint32_t idx_rx = 0;

        // Peek for incoming packets
        rcvd = xsk_ring_cons__peek(rx, 1, &idx_rx);
        if (rcvd > 0) {
            uint32_t idx_tx = 0;
            // Reserve a slot in the TX ring
            if (xsk_ring_prod__reserve(tx, 1, &idx_tx) > 0) {
                // In a real filter, you would inspect the packet buffer here
                // packet_data = xsk_umem__get_data(xsk->umem, ...);

                // Copy/Forward logic:
                // Copy frame from RX to TX descriptor
                *xsk_ring_prod__tx_desc(tx, idx_tx) = *xsk_ring_cons__rx_desc(rx, idx_rx);

                // Commit to hardware
                xsk_ring_prod__submit(tx, 1);
            }
            xsk_ring_cons__release(rx, 1);

            // Wakeup the kernel to send the packet
            sendto(xsk_socket__fd(xsk->xsk), NULL, 0, MSG_DONTWAIT, NULL, 0);
        }
    }
