struct Record<'a> {
    id: &'a str,
    value: &'a str,
}

// nom parser: parses "ID:Value"
fn parse_record(input: &str) -> IResult<&str, Record> {
    let (remaining, (id, value)) = separated_pair(
        take_until(":"),
        tag(":"),
        take_until("\n")
    )(input)?;

    Ok((remaining, Record { id, value }))
}

