/// in a CSV-like stream without allocating new Strings.
fn process_stream(reader: &mut BufReader<File>) -> io::Result<()> {
    let mut total_sum: u64 = 0;

    // We process the stream line-by-line (or chunk-by-chunk)
    // The buffer is reused by the reader, minimizing allocations.
    let mut line = String::with_capacity(1024); 

