/// A simple, zero-copy parser that sums the first column of a CSV file.
/// It uses only one buffer in memory, regardless of file size.
fn process_stream(path: &str) -> io::Result<f64> {
    let file = File::open(path)?;
    // Use a 64KB buffer, which fits well in L2 cache
    let reader = BufReader::with_capacity(64 * 1024, file);

    let mut total_sum = 0.0;

    for line in reader.lines() {
        let line = line?;
        // split_once uses an iterator and does not allocate a new Vector
        // It provides a reference (&str) to the existing line buffer
        if let Some((first_col, _rest)) = line.split_once(',') {
            if let Ok(val) = first_col.trim().parse::<f64>() {
                total_sum += val;
            }
        }
    }

    Ok(total_sum)
}

fn main() -> io::Result<()> {
    let path = "large_data.csv";
    let start = std::time::Instant::now();

    let result = process_stream(path)?;

    println!("Sum: {}, Time: {:?}", result, start.elapsed());
    Ok(())
}
```

