    let metadata = fs::metadata(LOG_FILE)?;

    if metadata.len() >= MAX_SIZE {
        // Atomic rename: This is a syscall that does not load data into RAM
        fs::rename(LOG_FILE, ROTATED_FILE)?;

        // Signal the application to reopen the file handle (or create a new one)
        // Creating a new file to replace the old one
        fs::File::create(LOG_FILE)?;
        println!("Log rotated successfully.");
    }
    Ok(())
}

