            let backup = format!("{}.1", LOG_FILE);

            // Atomically rename current log to backup
            fs::rename(LOG_FILE, backup)?;

            // Create a fresh file immediately
            OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .open(LOG_FILE)?;
        }
    }
    Ok(())
}

fn main() {
    println!("Log rotation daemon started...");

    // Main loop: minimal resource footprint
    loop {
        if let Err(e) = rotate_log() {
            eprintln!("Rotation error: {}", e);
        }

        // Sleep to yield CPU, preventing high power/CPU usage
        thread::sleep(Duration::from_secs(60));
    }
}
```

### Why this is memory-efficient:

1.  **Zero Runtime Overhead:** Rust compiles to static machine code with no garbage collector. The resident set size (RSS) of this binary is typically **less than 1MB** in memory.
2.  **No Dynamic Allocation Loop:** The `rotate_log` function performs file operations directly on the filesystem. It does not buffer the file content into RAM; it simply performs a `rename` and `create` operation, keeping memory usage constant regardless of the log file size.
3.  **Deterministic Resource Management:** Rust closes file handles as soon as they go out of scope (via the `Drop` trait), ensuring there are no hidden file descriptor leaks.
