use std::fs::File;
use std::io::{self, Read};
use std::time::Duration;
use tokio::signal::unix::{signal, SignalKind};

/// Reads basic CPU usage stats from /proc/stat
fn get_cpu_usage() -> io::Result<String> {
    let mut file = File::open("/proc/stat")?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;
    // We only care about the first line (aggregate cpu)
    Ok(contents.lines().next().unwrap_or("").to_string())
}

async fn run_monitor() {
    let mut interval = tokio::time::interval(Duration::from_secs(1));

    println!("Daemon started. Monitoring resources...");

    loop {
        tokio::select! {
            _ = interval.tick() => {
                match get_cpu_usage() {
                    Ok(stats) => println!("CPU Stats: {}", stats),
                    Err(e) => eprintln!("Failed to read stats: {}", e),
                }
            }
            // Graceful shutdown on SIGTERM/SIGINT
            _ = tokio::signal::ctrl_c() => {
                println!("\nShutdown signal received. Cleaning up...");
                break;
            }
        }
    }
}

#[tokio::main]
async fn main() -> io::Result<()> {
    // In a production daemon, you would implement double-forking 
    // or systemd notification here.
    run_monitor().await;
    println!("Daemon exited successfully.");
    Ok(())
}
```

