use std::time::Duration;
use tokio::time;
use systemstat::{System, Platform};
use syslog::{Facility, Formatter3164, BasicLogger};
use log::{info, LevelFilter};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // 1. Initialize Syslog
    let formatter = Formatter3164 {
        facility: Facility::LOG_DAEMON,
        hostname: None,
        process: "resource-monitor".into(),
        pid: std::process::id(),
    };
    let logger = syslog::unix(formatter)?;
    log::set_boxed_logger(Box::new(BasicLogger::new(logger)))
        .map(|()| log::set_max_level(LevelFilter::Info))?;

    info!("System monitor daemon started.");

    let sys = System::new();
    let mut interval = time::interval(Duration::from_secs(5));

    // 2. Main Daemon Loop
    loop {
        interval.tick().await;

        match sys.cpu_load_aggregate() {
            Ok(cpu) => {
                // Sleep briefly to capture CPU delta
                tokio::time::sleep(Duration::from_millis(1000)).await;
                match cpu.done() {
                    Ok(usage) => {
                        let load = 100.0 - usage.idle * 100.0;
                        info!("Current CPU usage: {:.2}%", load);
                    }
                    Err(e) => log::error!("CPU calculation error: {}", e),
                }
            }
            Err(e) => log::error!("Failed to monitor CPU: {}", e),
        }
    }
}
```

### Key Architectural Features of this Implementation:

1.  **Asynchronous Runtime (`tokio`):** Instead of blocking the CPU while waiting for a tick, the daemon uses a non-blocking event loop. This allows the process to remain idle and consume near-zero CPU resources until the next monitoring interval.
2.  **Memory Safety:** By using Rust, you eliminate common system-level vulnerabilities like buffer overflows or use-after-free errors, which are common targets when writing daemons in C/C++.
3.  **Syslog Integration:** Daemons should interact with standard OS logging facilities rather than stdout. This implementation routes output to `syslog`, allowing system administrators to manage logs via `journalctl` or `/var/log/syslog`.
4.  **Zero-Cost Abstractions:** The `systemstat` crate interacts directly with OS-level APIs (`/proc` on Linux). Because there is no managed runtime or VM, the memory footprint remains extremely low, making this ideal for long-running processes.

