use std::{fs, thread, time::Duration};
use std::io::{Read, Seek, SeekFrom};

/// A simple structure to hold CPU stats from /proc/stat
struct CpuStats {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
}

fn get_cpu_stats() -> Option<CpuStats> {
    let mut file = fs::File::open("/proc/stat").ok()?;
    let mut content = String::new();
    file.read_to_string(&mut content).ok()?;

    // First line of /proc/stat is aggregate CPU
    let line = content.lines().next()?;
    let parts: Vec<u64> = line.split_whitespace()
        .skip(1)
        .filter_map(|s| s.parse().ok())
        .collect();

    Some(CpuStats {
        user: parts[0],
        nice: parts[1],
        system: parts[2],
        idle: parts[3],
    })
}

fn main() {
    println!("Starting Resource Monitor Daemon...");

    let mut prev_stats = get_cpu_stats().expect("Failed to read CPU stats");

    loop {
        // Monitor interval
        thread::sleep(Duration::from_secs(1));

        if let Some(curr_stats) = get_cpu_stats() {
            let prev_total = prev_stats.user + prev_stats.nice + prev_stats.system + prev_stats.idle;
            let curr_total = curr_stats.user + curr_stats.nice + curr_stats.system + curr_stats.idle;

            let diff_idle = curr_stats.idle - prev_stats.idle;
            let diff_total = curr_total - prev_total;

            let cpu_usage = 100.0 * (1.0 - (diff_idle as f64 / diff_total as f64));

            println!("Current CPU Usage: {:.2}%", cpu_usage);

            // Here you would implement your "Management" logic 
            // e.g., if cpu_usage > 90.0 { kill_heavy_process(); }

            prev_stats = curr_stats;
        }
    }
}
```

