use sysinfo::{CpuExt, System, SystemExt};
use tokio::time::{self, Duration};

struct ResourceMonitor {
    sys: System,
}

impl ResourceMonitor {
    fn new() -> Self {
        Self {
            sys: System::new_all(),
        }
    }

    // Refresh and report metrics
    fn tick(&mut self) {
        self.sys.refresh_cpu();
        self.sys.refresh_memory();

        let cpu_usage = self.sys.global_cpu_info().cpu_usage();
        let mem_used = self.sys.used_memory();
        let mem_total = self.sys.total_memory();

        println!(
            "[Monitor] CPU: {:.2}% | RAM: {}/{} KB",
            cpu_usage, mem_used, mem_total
        );

        // Logic for management: e.g., if memory > 90%, log a warning
        if (mem_used as f64 / mem_total as f64) > 0.90 {
            eprintln!("[Alert] Critical memory threshold exceeded!");
        }
    }
}

