async fn main() {
    let mut monitor = ResourceMonitor::new();
    let mut interval = time::interval(Duration::from_secs(2));

    println!("System Daemon initialized. Monitoring...");

    loop {
        interval.tick().await;
        monitor.tick();
    }
}
