use std::fs::File;
use std::thread;
use std::time::Duration;
use std::io::{Read, Write};

fn get_cpu_load() -> String {
    // Reading from /proc/loadavg is the most efficient way on Linux
    let mut file = File::open("/proc/loadavg").expect("Failed to open /proc/loadavg");
    let mut contents = String::new();
    file.read_to_string(&mut contents).unwrap();
    contents.split_whitespace().take(3).collect::<Vec<_>>().join(", ")
}

fn main() {
    // 1. Define the daemon settings
    let stdout = File::create("/tmp/daemon.out").unwrap();
    let stderr = File::create("/tmp/daemon.err").unwrap();

    let daemonize = Daemonize::new()
        .pid_file("/tmp/sysmonitor.pid")
        .chown_pid_file(true)
        .working_directory("/tmp")
        .stdout(stdout)
        .stderr(stderr);

    // 2. Perform the fork/detach
    match daemonize.start() {
        Ok(_) => println!("Daemon started successfully."),
        Err(e) => eprintln!("Error starting daemon: {}", e),
    }

    // 3. The Monitor Loop (The daemon's core logic)
    loop {
        let load = get_cpu_load();

        // In a real system, you might trigger alerts, 
        // adjust resource limits (cgroups), or update a dashboard.
        if let Ok(mut file) = std::fs::OpenOptions::new()
            .append(true)
            .create(true)
            .open("/var/log/sys_monitor.log") 
        {
            let _ = writeln!(file, "Load average: {}", load);
        }

        // Sleep for 5 seconds before next polling cycle
        thread::sleep(Duration::from_secs(5));
    }
}
