```rust
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::thread;
use std::time::Duration;
use nix::sys::signal::{self, SigHandler, Signal};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

static RUNNING: AtomicBool = AtomicBool::new(true);

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // 1. Setup signal handling for graceful shutdown (SIGINT/SIGTERM)
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    }).expect("Error setting Ctrl-C handler");

    println!("Starting system monitor daemon...");

    // 2. Main Daemon Loop
    // We open the file once and seek back to the start to avoid 
    // overhead of opening/closing file descriptors every iteration.
    let mut load_file = File::open("/proc/loadavg")?;
    let mut buffer = String::with_capacity(32);

    while running.load(Ordering::SeqCst) {
        buffer.clear();
        load_file.seek(SeekFrom::Start(0))?;
        load_file.read_to_string(&mut buffer)?;

        // Simple parsing: just extract the 1-minute load average
        let load: Vec<&str> = buffer.split_whitespace().collect();
        if let Some(avg_1m) = load.first() {
            println!("[MONITOR] System Load (1m): {}", avg_1m);
        }

        // Low-latency sleep (non-blocking for hardware)
        thread::sleep(Duration::from_secs(2));
    }

    println!("Daemon shutting down gracefully.");
    Ok(())
}
```

### Why this approach is "High Performance":

1.  **Zero-Allocation Loop:** Inside the `while` loop, we reuse the same `String` buffer. By using `buffer.clear()`, we retain the existing memory capacity, preventing the heap allocator from triggering during monitoring cycles.
2.  **File Descriptor Reuse:** We open `/proc/loadavg` once at the start of the program. Repeatedly opening and closing files is an expensive system call that involves searching the filesystem hierarchy; reusing the descriptor is significantly faster.
3.  **Atomic Safety:** By using `AtomicBool`, we avoid mutex-locking overhead when checking if the daemon should continue running. This ensures the loop remains tight and predictable.
4.  **No GC Pauses:** Because this is Rust, there is no Garbage Collector periodically scanning the memory to see if objects are still in use. The daemon will maintain a consistent memory footprint and latency profile regardless of how long it runs.

