#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250

// Basic packet processing loop
static void port_init(uint16_t port) {
    struct rte_eth_conf port_conf = {0};
    // Initialize port with 1 queue for simplicity
    rte_eth_dev_configure(port, 1, 1, &port_conf);
    rte_eth_rx_queue_setup(port, 0, RX_RING_SIZE, rte_socket_id(), NULL, NULL);
    rte_eth_dev_start(port);
}

