### 1. The eBPF Program (`flow_counter.bpf.c`)
This code runs in kernel space. It increments a map whenever a packet is received, allowing you to monitor traffic without copying data to user space.

```c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

// A map to store packet counts by protocol
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 256);
    __type(key, __u8);
    __type(value, __u64);
} flow_stats SEC(".maps");

SEC("xdp")
int count_packets(struct xdp_md *ctx) {
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    // Minimal header parsing: Assume Ethernet -> IP
    struct ethhdr *eth = data;
    if (data + sizeof(*eth) > data_end) return XDP_PASS;

    // Only handle IPv4 for this example
    if (eth->h_proto != bpf_htons(ETH_P_IP)) return XDP_PASS;

    struct iphdr *iph = data + sizeof(*eth);
    if ((void *)iph + sizeof(*iph) > data_end) return XDP_PASS;

    __u8 proto = iph->protocol;
    __u64 *count = bpf_map_lookup_elem(&flow_stats, &proto);
    if (count) {
        __sync_fetch_and_add(count, 1);
    }

    return XDP_PASS; // Pass to kernel stack
}
```

### 2. The User-Space Loader (`main.rs`)
This Rust code loads the eBPF program, attaches it to the network interface, and reads the metrics.

```rust
use aya::maps::HashMap;
use aya::programs::Xdp;
use aya::Bpf;

#[tokio::main]
async fn main() -> Result<(), anyhow::Error> {
    // Load the BPF bytecode
    let mut bpf = Bpf::load(include_bytes_aligned!("flow_counter.o"))?;

    // Attach to the network interface (e.g., eth0)
    let program: &mut Xdp = bpf.program_mut("count_packets").unwrap().try_into()?;
    program.load()?;
    program.attach("eth0", aya::programs::XdpFlags::default())?;

    // Periodically poll the map for results
    let mut stats = HashMap::try_from(bpf.map_mut("flow_stats").unwrap())?;

    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
        for entry in stats.iter() {
            let (proto, count) = entry?;
            println!("Protocol {}: {} packets", proto, count);
        }
    }
}
```

### Why this is the "Gigabit-Scale" solution:

1.  **Zero-Copy:** The eBPF program inspects packet headers directly in the RX ring buffer memory. No context switching between kernel and user space occurs for the packet processing itself.
2.  **Safety:** By using Rust for the user-space loader, you ensure that the metrics management and alerting systems are memory-safe and won't crash when under extreme load.
