// A map to store flow data: key is source IP, value is total bytes
#[map]
static mut FLOW_STATS: HashMap<u32, u64> = HashMap::with_max_entries(10240, 0);

#[xdp(name="flow_analyzer")]
pub fn flow_analyzer(ctx: XdpContext) -> u32 {
    let eth_proto = u16::from_be(ctx.load::<u16>(12).unwrap_or(0));

