            unsafe { *stats += len; }
        } else {
            let _ = unsafe { FLOW_STATS.insert(&src_ip, &len, 0) };
        }
    }

    // Pass the packet to the OS
    aya_bpf::bindings::xdp_action::XDP_PASS
}
