This code runs at the NIC driver level. It counts packets per flow (Source IP).

```c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

// Map to store flow data (Source IP -> Packet Count)
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 10240);
    __type(key, __u32);   // Source IP
    __type(value, __u64); // Packet Count
} flow_stats SEC(".maps");

SEC("xdp")
int xdp_flow_monitor(struct xdp_md *ctx) {
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    struct ethhdr *eth = data;
    if (data + sizeof(struct ethhdr) > data_end) return XDP_PASS;

    if (eth->h_proto == htons(ETH_P_IP)) {
        struct iphdr *iph = data + sizeof(struct ethhdr);
        if (data + sizeof(struct ethhdr) + sizeof(struct iphdr) > data_end) return XDP_PASS;

        __u32 src_ip = iph->saddr;
        __u64 *count = bpf_map_lookup_elem(&flow_stats, &src_ip);

        if (count) {
            *count += 1;
        } else {
            __u64 init_val = 1;
            bpf_map_update_elem(&flow_stats, &src_ip, &init_val, BPF_ANY);
        }
    }

    return XDP_PASS; // Pass to stack after analysis
}

char _license[] SEC("license") = "GPL";
```

