class PIDController {
public:
    double Kp, Ki, Kd, prev_error = 0, integral = 0;

    double update(double target, double measured, double dt) {
        double error = target - measured;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;
        prev_error = error;
        return (Kp * error) + (Ki * integral) + (Kd * derivative);
    }
};

