#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 10
#define THRESHOLD 3.0 // Multiplier for standard deviation

typedef struct {
    float buffer[WINDOW_SIZE];
    int head;
    float sum;
    float sum_sq;
} RollingStats;

// Add new sample and update running sums for O(1) complexity
void update_stats(RollingStats *stats, float new_val) {
    float old_val = stats->buffer[stats->head];

    // Remove old value from sums
    stats->sum -= old_val;
    stats->sum_sq -= (old_val * old_val);

    // Add new value
    stats->buffer[stats->head] = new_val;
    stats->sum += new_val;
    stats->sum_sq += (new_val * new_val);

    stats->head = (stats->head + 1) % WINDOW_SIZE;
}

bool is_anomalous(RollingStats *stats, float val) {
    float mean = stats->sum / WINDOW_SIZE;
    float variance = (stats->sum_sq / WINDOW_SIZE) - (mean * mean);
    float std_dev = sqrtf(variance > 0 ? variance : 0);

    // Detect if value is beyond N standard deviations
    return (fabsf(val - mean) > (THRESHOLD * std_dev + 0.1f)); // +0.1 for noise floor
}

int main() {
