### The Algorithm
We calculate the **Z-score** ($Z = \frac{|x - \mu|}{\sigma}$). If the Z-score exceeds a threshold, the data point is considered an anomaly.

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define ALPHA 0.1       // Smoothing factor for moving average
#define THRESHOLD 3.0   // Z-score threshold for anomaly detection

typedef struct {
    float mean;
    float variance;
    bool initialized;
} AnomalyDetector;

// Update the detector with a new sample and return true if anomalous
bool process_sample(AnomalyDetector *detector, float sample) {
    if (!detector->initialized) {
        detector->mean = sample;
        detector->variance = 0.0f;
        detector->initialized = true;
        return false;
    }

    float std_dev = sqrtf(detector->variance);
    float diff = fabsf(sample - detector->mean);

    // Check if the current sample is an anomaly (Z-score > Threshold)
    // Avoid division by zero if std_dev is too small
    bool is_anomaly = (std_dev > 0.1f) && (diff > THRESHOLD * std_dev);

    // Online Welford-like update of mean and variance (EMA approach)
    float delta = sample - detector->mean;
    detector->mean += ALPHA * delta;
    detector->variance = (1.0f - ALPHA) * (detector->variance + ALPHA * delta * delta);

    return is_anomaly;
}

int main() {
    AnomalyDetector acc_x = {0, 0, false};

    // Simulated sensor stream
    float sensor_data[] = {1.0, 1.1, 1.0, 0.9, 1.0, 5.0, 1.0}; // 5.0 is the anomaly

    for (int i = 0; i < 7; i++) {
        bool anomaly = process_sample(&acc_x, sensor_data[i]);
        if (anomaly) {
            printf("Anomaly detected at index %d: Value %.2f\n", i, sensor_data[i]);
        } else {
            printf("Sample %.2f OK\n", sensor_data[i]);
        }
    }

    return 0;
}
```

