#include <iostream>
#include <vector>
#include <cmath>
#include <numeric>

class AnomalyDetector {
private:
    float threshold;
    std::vector<float> window;
    size_t window_size;

public:
    AnomalyDetector(size_t size, float t) : window_size(size), threshold(t) {}

    bool isAnomaly(float sample) {
        if (window.size() < window_size) {
            window.push_back(sample);
            return false;
        }

        // Calculate mean
        float sum = std::accumulate(window.begin(), window.end(), 0.0f);
        float mean = sum / window_size;

        // Calculate standard deviation
        float sq_sum = 0;
        for (float val : window) sq_sum += (val - mean) * (val - mean);
        float stdev = std::sqrt(sq_sum / window_size);

        // Update sliding window (remove oldest, add newest)
        window.erase(window.begin());
        window.push_back(sample);

        // Anomaly Detection Logic (Z-score)
        // If stdev is 0, we avoid division; treat as non-anomaly
        if (stdev == 0) return false;
        return std::abs(sample - mean) > (threshold * stdev);
    }
};

