// A circular buffer to store a window of accelerometer readings
class AccelerometerBuffer {
private:
    std::vector<float> buffer;
    size_t head = 0;
    bool full = false;

public:
    AccelerometerBuffer(size_t size) : buffer(size, 0.0f) {}

    void add(float val) {
        buffer[head] = val;
        head = (head + 1) % buffer.size();
        if (head == 0) full = true;
    }

    float get_mean() const {
        float sum = std::accumulate(buffer.begin(), buffer.end(), 0.0f);
        return sum / buffer.size();
    }

    float get_std_dev(float mean) const {
        float sq_sum = 0;
        for (float val : buffer) sq_sum += (val - mean) * (val - mean);
        return std::sqrt(sq_sum / buffer.size());
    }
};

