### C++ Implementation

```cpp
#include <cmath>
#include <vector>

// Configuration
const int WINDOW_SIZE = 50;
const float THRESHOLD = 3.0f; // Standard deviations to trigger anomaly

class AnomalyDetector {
private:
    std::vector<float> buffer;
    float sum = 0.0f;
    float sq_sum = 0.0f;
    int index = 0;
    bool buffer_full = false;

public:
    // Calculate Magnitude: sqrt(x^2 + y^2 + z^2)
    float calculateMagnitude(float x, float y, float z) {
        return std::sqrt(x * x + y * y + z * z);
    }

    bool processSample(float x, float y, float z) {
        float val = calculateMagnitude(x, y, z);

        if (!buffer_full) {
            buffer.push_back(val);
            sum += val;
            sq_sum += (val * val);
            if (buffer.size() >= WINDOW_SIZE) buffer_full = true;
            return false; // Not enough data yet
        }

        // Calculate statistics
        float mean = sum / WINDOW_SIZE;
        float variance = (sq_sum / WINDOW_SIZE) - (mean * mean);
        float std_dev = std::sqrt(variance > 0 ? variance : 0);

        // Anomaly Detection: Z-Score > Threshold
        bool is_anomaly = (std_dev > 0) && (std::abs(val - mean) > THRESHOLD * std_dev);

        // Update sliding window (Remove oldest, add newest)
        float oldest = buffer[index];
        sum = sum - oldest + val;
        sq_sum = sq_sum - (oldest * oldest) + (val * val);
        buffer[index] = val;
        index = (index + 1) % WINDOW_SIZE;

        return is_anomaly;
    }
};

