    float mean = 0.0f;
    float m2 = 0.0f; // Sum of squares of differences from the mean
    int count = 0;
    const float threshold = 3.0f; // Z-score threshold

public:
    // Welford's algorithm for online variance calculation
    bool isAnomaly(float new_sample) {
        count++;
        float delta = new_sample - mean;
        mean += delta / count;
        float delta2 = new_sample - mean;
        m2 += delta * delta2;

        if (count < 10) return false; // Warm-up period

        float variance = m2 / (count - 1);
        float stdDev = std::sqrt(variance);

        // Return true if deviation is greater than threshold * stdDev
        return (std::abs(new_sample - mean) > threshold * stdDev);
    }
};

