#![no_std]
#![no_main]

use panic_halt as _; // Panic handler for embedded
use embedded_hal::adc::OneShot;
use embedded_hal::digital::v2::OutputPin;

// Simple Moving Average filter state
struct Filter {
    buffer: [u16; 4],
    index: usize,
}

impl Filter {
    fn update(&mut self, new_val: u16) -> u16 {
        self.buffer[self.index] = new_val;
        self.index = (self.index + 1) % 4;

        // Return average (sum / length)
        self.buffer.iter().sum::<u16>() / 4
    }
}

#[entry]
fn main() -> ! {
    // Hardware initialization (abstracted per platform)
    let peripherals = hal::pac::Peripherals::take().unwrap();
    let mut adc = peripherals.ADC1;
    let mut sensor_pin = peripherals.PA0;
    let mut actuator = peripherals.PA1.into_push_pull_output();

    let mut filter = Filter { buffer: [0; 4], index: 0 };
    let threshold: u16 = 500;

    loop {
        // 1. Read raw sensor data
        if let Ok(raw_val) = adc.read(&mut sensor_pin) {

            // 2. Filter the signal
            let filtered_val = filter.update(raw_val);

            // 3. Manage Actuator based on filtered data
            if filtered_val > threshold {
                actuator.set_high().ok();
            } else {
                actuator.set_low().ok();
            }
        }

        // Add small delay/debounce logic here if required by hardware
    }
}
```

