### Sensor-Actuator Control Logic (C)

```c
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 8
#define THRESHOLD 500

// Simple Moving Average Filter structure
typedef struct {
    uint16_t buffer[WINDOW_SIZE];
    uint8_t head;
    uint32_t sum;
} MovingAverage;

// Initialize filter
void filter_init(MovingAverage *f) {
    f->head = 0;
    f->sum = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) f->buffer[i] = 0;
}

// Update filter with new sensor value
uint16_t filter_update(MovingAverage *f, uint16_t new_val) {
    f->sum -= f->buffer[f->head];      // Remove oldest
    f->buffer[f->head] = new_val;      // Add new
    f->sum += new_val;
