#include <stdint.h>

// Configuration for a small moving average filter (Low memory footprint)
#define WINDOW_SIZE 4
#define THRESHOLD 500  // Actuator trigger value

// Circular buffer to store sensor readings
static uint16_t sensor_buffer[WINDOW_SIZE] = {0};
static uint8_t buffer_index = 0;

// Mock Hardware Abstraction Layer (HAL) functions
extern uint16_t read_sensor_raw();
extern void set_actuator_state(uint8_t state);

/**
 * Filters incoming data using a simple moving average.
 * Memory Complexity: O(N) where N is WINDOW_SIZE
 */
uint16_t filter_data(uint16_t new_value) {
    static uint32_t sum = 0;

    // Subtract oldest value and add new value
    sum -= sensor_buffer[buffer_index];
    sensor_buffer[buffer_index] = new_value;
    sum += new_value;

    // Update circular buffer index
    buffer_index = (buffer_index + 1) % WINDOW_SIZE;

    return (uint16_t)(sum / WINDOW_SIZE);
}

