        uint16_t raw_val = read_sensor_raw();

        // 2. Process/Filter (Edge Intelligence)
        uint16_t filtered_val = filter_data(raw_val);

        // 3. Actuate based on threshold
        if (filtered_val > THRESHOLD) {
            set_actuator_state(1); // Turn ON
        } else {
            set_actuator_state(0); // Turn OFF
        }

        // 4. Delay/Sleep to manage power/frequency
        // delay(10); 
    }
}
