```csharp
using Godot;
using System;

public partial class Player : CharacterBody2D
{
    [Export] public float Speed = 300.0f;
    [Export] public float JumpVelocity = -400.0f;

    // Get the gravity from the project settings to be synced with RigidBody nodes.
    public float Gravity = ProjectSettings.GetSetting("physics/2d/default_gravity").AsSingle();

    private AnimatedSprite2D _sprite;

    public override void _Ready()
    {
        // Reference the animation component
        _sprite = GetNode<AnimatedSprite2D>("AnimatedSprite2D");
    }

    public override void _PhysicsProcess(double delta)
    {
        Vector2 velocity = Velocity;

        // 1. Add Gravity
        if (!IsOnFloor())
            velocity.Y += Gravity * (float)delta;

        // 2. Handle Jump
        if (Input.IsActionJustPressed("ui_accept") && IsOnFloor())
            velocity.Y = JumpVelocity;

        // 3. Get Input Direction (-1 for left, 1 for right)
        float direction = Input.GetAxis("ui_left", "ui_right");
        if (direction != 0)
        {
            velocity.X = direction * Speed;
            _sprite.FlipH = (direction < 0); // Flip sprite based on direction
            _sprite.Play("run");             // Trigger run animation
        }
        else
        {
            velocity.X = Mathf.MoveToward(Velocity.X, 0, Speed);
            _sprite.Play("idle");            // Trigger idle animation
        }

        Velocity = velocity;
        MoveAndSlide(); // Built-in physics collision resolution
    }
}
```

### How to set this up in Godot:
1.  **Nodes:** Create a `CharacterBody2D` node. Add a `CollisionShape2D` (a rectangle for the player's hitbox) and an `AnimatedSprite2D` as children.
2.  **Animation:** In the `AnimatedSprite2D` inspector, create a "SpriteFrames" resource. Add two animations: "idle" and "run," and drop your sprite sheet images into them.
3.  **Physics:** Go to *Project Settings > Input Map* and ensure the actions `ui_left`, `ui_right`, and `ui_accept` (spacebar) are defined.
4.  **Integration:** Attach the C# script above to your `CharacterBody2D`.

### Why this approach works:
*   **Physics Simulation:** By inheriting from `CharacterBody2D` and using `MoveAndSlide()`, you gain access to Godot’s high-performance physics engine. It automatically handles sliding against walls, floor detection, and slope climbing without you needing to write a single line of collision detection code.
*   **Sprite Animation:** The `AnimatedSprite2D` node acts as a state machine. By calling `.Play("animation_name")`, the engine handles frame timing, looping, and transitions for you automatically.
*   **Scalability:** Because this is C#, as your game grows, you can easily add complex systems (like inventory, sound effects, or AI) using standard Object-Oriented Programming principles.

