import * as THREE from 'three';

// 1. Setup Scene
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer();
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// 2. Custom Shader Material (Visual Effect)
const vertexShader = `
  varying vec3 vNormal;
  void main() {
    vNormal = normalize(normalMatrix * normal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const fragmentShader = `
  varying vec3 vNormal;
  uniform float time;
  void main() {
    // Dynamic effect: color cycles based on time and normal direction
    vec3 color = vec3(0.5 + 0.5 * sin(time), vNormal.y, vNormal.z);
    gl_FragColor = vec4(color, 1.0);
  }
`;

const material = new THREE.ShaderMaterial({
  uniforms: { time: { value: 0 } },
  vertexShader,
  fragmentShader
});

// 3. Create Object
const geometry = new THREE.SphereGeometry(1, 32, 32);
const sphere = new THREE.Mesh(geometry, material);
scene.add(sphere);

// 4. Dynamic Lighting
const light = new THREE.DirectionalLight(0xffffff, 1);
light.position.set(5, 5, 5);
scene.add(light);
scene.add(new THREE.AmbientLight(0x404040)); // Soft white light

camera.position.z = 5;

// 5. Animation Loop
function animate(time: number) {
  requestAnimationFrame(animate);

  // Update shader uniform
  material.uniforms.time.value = time * 0.002;

  // Rotate object
  sphere.rotation.x += 0.01;
  sphere.rotation.y += 0.01;

  renderer.render(scene, camera);
}

animate(0);
