```javascript
import * as THREE from 'three';

// 1. Scene setup
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
document.getElementById('viewer').appendChild(renderer.domElement);

// 2. Dynamic Geometry
const geometry = new THREE.TorusKnotGeometry(1, 0.3, 100, 16);
const material = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.2, metalness: 0.8 });
const torus = new THREE.Mesh(geometry, material);
scene.add(torus);

// 3. Dynamic Lighting
const pointLight = new THREE.PointLight(0xff0000, 50, 100);
scene.add(pointLight);
scene.add(new THREE.AmbientLight(0x404040)); // Soft white light

camera.position.z = 5;

// 4. Animation Loop
function animate(time) {
    requestAnimationFrame(animate);

    // Animate the light source
    const t = time * 0.002;
    pointLight.position.x = Math.sin(t) * 3;
    pointLight.position.y = Math.cos(t) * 3;
    pointLight.position.z = Math.sin(t) * 2;

    // Rotate the object
    torus.rotation.x += 0.01;
    torus.rotation.y += 0.01;

    renderer.render(scene, camera);
}

animate(0);
```

### Why this works:
*   **Dynamic Lighting:** The `PointLight` is updated every frame in the `animate` loop. Because `MeshStandardMaterial` is a physically-based shader, it automatically calculates reflections, shadows, and light fall-off based on the light's new coordinates.
