  uniforms: { time: { value: 0 } },
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform float time;
    varying vec2 vUv;
    void main() {
      gl_FragColor = vec4(0.5 + 0.5 * sin(vUv.x * 10.0 + time), 0.5, 0.5 + 0.5 * cos(vUv.y * 10.0 + time), 1.0);
    }
  `
});

// 3. Objects
const sphere = new THREE.Mesh(new THREE.SphereGeometry(1, 32, 32), shaderMaterial);
scene.add(sphere);

// 4. Dynamic Lighting
const pointLight = new THREE.PointLight(0xffffff, 10, 100);
scene.add(pointLight);
scene.add(new THREE.AmbientLight(0x404040)); // Soft base light

camera.position.z = 5;

// 5. Animation Loop
function animate(t: number) {
  requestAnimationFrame(animate);

  // Animate Shader
  shaderMaterial.uniforms.time.value = t * 0.002;

  // Animate Light (Dynamic Lighting)
  pointLight.position.x = Math.sin(t * 0.001) * 3;
  pointLight.position.y = Math.cos(t * 0.001) * 3;

  renderer.render(scene, camera);
}

animate(0);
```

