### CustomPhysicsComponent.cpp
```cpp
#include "CustomPhysicsPlugin.h"

void CustomPhysicsPlugin::ApplyForce(PhysicsBody& body, const float force[3], float deltaTime) {
    if (body.mass <= 0.0f) return;

    // F = ma  =>  a = F / m
    float acceleration[3] = {
        force[0] / body.mass,
        force[1] / body.mass,
        force[2] / body.mass
    };

    // Update velocity: v = v + a * dt
    for (int i = 0; i < 3; ++i) {
        body.velocity[i] += acceleration[i] * deltaTime;
    }

    // Update position: p = p + v * dt
    for (int i = 0; i < 3; ++i) {
        body.position[i] += body.velocity[i] * deltaTime;
    }
}
```

