This uses the **Semi-implicit Euler integration** method, which is the industry standard for games because it is more stable than explicit Euler.

```cpp
#include "PhysicsIntegrator.h"

void PhysicsPlugin::Update(float deltaTime) {
    for (auto& body : bodies) {
        if (body.is_static) continue;

        // 1. Apply Gravity: v = v + a * dt
        body.velocity.x += gravity.x * deltaTime;
        body.velocity.y += gravity.y * deltaTime;
        body.velocity.z += gravity.z * deltaTime;

        // 2. Update Position: p = p + v * dt
        body.position.x += body.velocity.x * deltaTime;
        body.position.y += body.velocity.y * deltaTime;
        body.position.z += body.velocity.z * deltaTime;
    }
}

