#include "Vector3.h" // Assuming a custom math library

class PhysicsComponent {
public:
    PhysicsComponent(float mass);

    // The integration step
    void Update(float deltaTime);

    void AddForce(const Vector3& force);

private:
    float mass;
    float invMass; // Precomputed 1/mass

    Vector3 velocity;
    Vector3 position;
    Vector3 forceAccumulator;
};
```

#### `PhysicsComponent.cpp`
This contains the "Solver" logic. In a commercial engine, this code would run inside the engine's `Tick` or `FixedUpdate` function.

```cpp
#include "PhysicsComponent.h"

PhysicsComponent::PhysicsComponent(float mass) : mass(mass) {
    invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f; // Infinite mass for static objects
}

void PhysicsComponent::AddForce(const Vector3& force) {
    forceAccumulator += force;
}

void PhysicsComponent::Update(float deltaTime) {
    if (invMass <= 0.0f) return; // Static objects don't move

    // 1. Acceleration: F = ma  => a = F / m
    Vector3 acceleration = forceAccumulator * invMass;

    // 2. Velocity integration: v = v + a * dt
    velocity += acceleration * deltaTime;

    // 3. Position integration: p = p + v * dt
    position += velocity * deltaTime;

    // 4. Reset force accumulator for the next frame
    forceAccumulator = Vector3(0, 0, 0);
}
```

