        body.velocity.y += (body.force.y / body.mass) * dt;

        // 2. Update position
        body.position.x += body.velocity.x * dt;
        body.position.y += body.velocity.y * dt;

        // 3. Reset forces
        body.force = {0.0f, 0.0f};
    }
};

