    float x, y;
    float oldX, oldY;
    float velX, velY;
    float acceleration = 9.81f; // Gravity
};

class PhysicsEngine {
    const float fixedDeltaTime = 0.016f; // Target 60Hz (16ms)
    RigidBody ball = {0.0f, 100.0f, 0.0f, 100.0f, 0.0f, 0.0f};

public:
    void update(float dt) {
        // Verlet Integration for stability
        float vx = ball.x - ball.oldX;
        float vy = ball.y - ball.oldY;

        ball.oldX = ball.x;
        ball.oldY = ball.y;

        ball.x += vx + 0.0f * (dt * dt); // 0.0 is acceleration X
        ball.y += vy + ball.acceleration * (dt * dt);

        std::cout << "Ball Position: (" << ball.x << ", " << ball.y << ")\n";
    }

    void run() {
        auto lastTime = std::chrono::high_resolution_clock::now();
        float accumulator = 0.0f;

        while (true) {
            auto currentTime = std::chrono::high_resolution_clock::now();
            float frameTime = std::chrono::duration<float>(currentTime - lastTime).count();
            lastTime = currentTime;

            accumulator += frameTime;

            // Consume time in fixed chunks to maintain deterministic physics
            while (accumulator >= fixedDeltaTime) {
                update(fixedDeltaTime);
                accumulator -= fixedDeltaTime;
            }

            // Optional: Render() call goes here
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    }
};

int main() {
