use std::sync::{Arc, Mutex};
use std::collections::HashMap;

// Using a struct for currency prevents floating-point rounding errors
// common in financial applications (e.g., 0.1 + 0.2 != 0.3)
#[derive(Debug, Clone, Copy)]
struct Money(u64); // Represented in cents

struct Account {
    balance: Money,
}

struct PaymentProcessor {
    // Arc allows shared ownership, Mutex ensures thread-safe mutation
    accounts: Arc<Mutex<HashMap<String, Account>>>,
}

impl PaymentProcessor {
    fn new() -> Self {
        Self { accounts: Arc::new(Mutex::new(HashMap::new())) }
    }

    fn process_payment(&self, from: &str, to: &str, amount: Money) -> Result<(), String> {
        let mut accounts = self.accounts.lock().map_err(|_| "Lock poisoned")?;

        let sender = accounts.get_mut(from).ok_or("Sender not found")?;
        if sender.balance.0 < amount.0 {
            return Err("Insufficient funds".to_string());
        }

        let receiver = accounts.get_mut(to).ok_or("Receiver not found")?;

        // Perform the transaction
        sender.balance.0 -= amount.0;
        receiver.balance.0 += amount.0;

        println!("Processed: {} cents from {} to {}", amount.0, from, to);
        Ok(())
    }
}

fn main() {
    let processor = PaymentProcessor::new();

    // Seed initial state
    {
        let mut accounts = processor.accounts.lock().unwrap();
        accounts.insert("Alice".to_string(), Account { balance: Money(1000) });
        accounts.insert("Bob".to_string(), Account { balance: Money(500) });
    }

    // Process a transaction
    match processor.process_payment("Alice", "Bob", Money(200)) {
        Ok(_) => println!("Transaction successful."),
        Err(e) => println!("Transaction failed: {}", e),
    }
}
```

