```csharp
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Azure.Identity;
using Microsoft.Data.SqlClient;

var builder = WebApplication.CreateBuilder(args);

// 1. Setup Managed Identity for Azure services
// This automatically picks up the service identity in Azure (App Service, AKS, or VM)
var credential = new DefaultAzureCredential();

// 2. Register Services
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();

var app = builder.Build();

// 3. Middleware for Production Security
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}
else
{
    // Ensure HTTPS redirection in Azure
    app.UseHttpsRedirection();
}

// 4. Secure Endpoint Example
app.MapGet("/api/data", async () => 
{
    // Example: Connecting to Azure SQL using Managed Identity
    // No passwords needed in the connection string
    var connectionString = builder.Configuration.GetConnectionString("AzureSql");
    using var connection = new SqlConnection(connectionString);

    // Set the token provider to use the Managed Identity
    connection.AccessToken = (await credential.GetTokenAsync(
        new Azure.Core.TokenRequestContext(new[] { "https://database.windows.net/" }))).Token;

    await connection.OpenAsync();
    return Results.Ok(new { status = "Securely connected to Azure SQL" });
})
.WithName("GetSecureData")
.WithOpenApi();

app.Run();
```

